import { CAPACITY, SHIFTS, ROOMS, roomsForShift, minutes, blankState, validateState } from './model.js';

const ICONS = {
  grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M15 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',
  book:'<path d="M12 5.5C9 3.5 5 3.5 2 4.5v15c3-1 7-1 10 1 3-2 7-2 10-1v-15c-3-1-7-1-10 1Zm0 0v15"/>',
  teacher:'<path d="m2 8 10-5 10 5-10 5L2 8Zm4 2v7c4 3 8 3 12 0v-7m4-2v8"/>',
  calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-13 5h2m4 0h2"/>',
  door:'<path d="M4 21h16M6 21V4l12-2v19M14 12h.01"/>',
  settings:'<path d="m9 3-1 3-3 1v3l-2 2 2 2v3l3 1 1 3h6l1-3 3-1v-3l2-2-2-2V7l-3-1-1-3H9Z"/><circle cx="12" cy="12" r="3"/>',
  search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
  bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
  chevron:'<path d="m9 6 6 6-6 6"/>',
  down:'<path d="m6 9 6 6 6-6"/>',
  left:'<path d="m15 6-6 6 6 6"/>',
  sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',
  sunset:'<path d="M3 17h18M6 14a6 6 0 0 1 12 0M12 2v3M3 6l2 2m14 0 2-2M5 21h14"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
  help:'<circle cx="12" cy="12" r="9"/><path d="M9.1 9a3 3 0 0 1 5.8 1c0 2-3 2-3 4m0 3h.01"/>',
  close:'<path d="m6 6 12 12M6 18 18 6"/>',
  edit:'<path d="m15 4 5 5M4 20l5-1L21 7a3.5 3.5 0 0 0-5-5L4 14l-1 7 1-1Z"/>',
  trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
  upload:'<path d="M12 15V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',
  menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
  spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',
  mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',
  folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7Z"/>'
};
const I = (name, cls = '') => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name] || ICONS.grid}</svg>`;
const E = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $ = (selector, root = document) => root.querySelector(selector);
const key = 'forma-school-crm-v1';
const localDate = date => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const today = () => localDate(new Date());
const parseDate = d => new Date(`${d}T12:00:00`);
const addDays = (d, n) => { const date = parseDate(d); date.setDate(date.getDate()+n); return localDate(date); };
const monday = d => addDays(d, -((parseDate(d).getDay()+6)%7));
const dateFmt = (d, opts = {day:'numeric',month:'long',year:'numeric'}) => parseDate(d).toLocaleDateString('it-IT',opts);
const initials = p => `${p.firstName[0] || ''}${p.lastName[0] || ''}`.toUpperCase();
const fullName = p => p ? `${p.firstName} ${p.lastName}` : 'Da assegnare';
const roomName = id => ROOMS.find(r => r.id === id)?.name || 'Da assegnare';
const className = id => db.classes.find(c => c.id === id)?.name || 'Nessuna classe';
const teacherName = id => fullName(db.teachers.find(t => t.id === id));
const enrolled = id => db.students.filter(s => s.classId === id);
const statusLabels = {planned:'In partenza',active:'Attiva',finished:'Conclusa',waiting:'In attesa',inactive:'Non attivo'};
const statusPill = (status, student = false) => `<span class="pill ${status === 'active' ? 'green' : status === 'planned' || status === 'waiting' ? 'gold' : 'gray'}"><i class="dot ${status === 'active' ? 'green' : status === 'planned' || status === 'waiting' ? 'gold' : ''}"></i>${student && status === 'active' ? 'Attivo' : E(statusLabels[status] || status)}</span>`;
let storageNotice = '';
let db = blankState();
try { const stored = localStorage.getItem(key); if (stored) { const parsed = JSON.parse(stored); const error = validateState(parsed); if (error) storageNotice = 'L’archivio salvato non è leggibile. Esportalo dalle impostazioni prima di sostituirlo.'; else db = parsed; } } catch { storageNotice = 'Il salvataggio del browser non è disponibile. Esporta una copia dei dati dalle impostazioni.'; }
let view = location.hash.slice(1) || 'panoramica';
const pages = {panoramica:'Panoramica',allievi:'Allievi',classi:'Classi e corsi',docenti:'Docenti',calendario:'Calendario',aule:'Aule',impostazioni:'Impostazioni'};
if (!pages[view]) view = 'panoramica';
let selectedDate = today(), calendarWeek = monday(today()), roomShift = 'morning', roomDate = today();
const filters = {allievi:{q:'',status:'all'},classi:{q:'',shift:'all'},docenti:{q:''}};
let toastTimer;
const app = $('#app'), modal = $('#modal');

function toast(message) { const el = $('#toast'); el.textContent = message; el.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('show'), 4300); }
function commit(change, message) {
  const next = structuredClone(db); change(next);
  const error = validateState(next); if (error) return error;
  try { localStorage.setItem(key, JSON.stringify(next)); } catch { return 'Impossibile salvare nel browser. Libera spazio o abilita l’archiviazione e riprova.'; }
  db = next; storageNotice = ''; render(); if (message) toast(message); return '';
}
function activity(next, text) { next.activities.unshift({text,at:new Date().toISOString()}); next.activities = next.activities.slice(0,50); }
function go(page) { if (location.hash === `#${page}`) { view = page; render(); } else location.hash = page; }
function navLink(page, icon, badge) { return `<a href="#${page}" class="${view === page ? 'active' : ''}" ${view === page ? 'aria-current="page"' : ''}>${I(icon)}<span>${pages[page]}</span>${badge !== undefined && badge > 0 ? `<span class="count">${badge}</span>` : ''}</a>`; }
function bannerArt() { return `<svg class="banner-art" viewBox="0 0 250 170" fill="none" aria-hidden="true"><ellipse cx="132" cy="154" rx="101" ry="8" fill="#ddd2ef" opacity=".6"/><rect x="69" y="29" width="126" height="111" rx="11" transform="rotate(9 69 29)" fill="#d9c9ef"/><rect x="57" y="19" width="126" height="118" rx="11" transform="rotate(-5 57 19)" fill="white" stroke="#dfd3ef"/><path d="m62 48 122-11" stroke="#eee7f8" stroke-width="2"/><path d="m82 13 1 15m71-22 1 15" stroke="#af92d4" stroke-width="5" stroke-linecap="round"/><rect x="76" y="62" width="20" height="18" rx="4" transform="rotate(-5 76 62)" fill="#eee6fa"/><rect x="109" y="59" width="20" height="18" rx="4" transform="rotate(-5 109 59)" fill="#eee6fa"/><rect x="142" y="56" width="20" height="18" rx="4" transform="rotate(-5 142 56)" fill="#eee6fa"/><rect x="79" y="93" width="20" height="18" rx="4" transform="rotate(-5 79 93)" fill="#eee6fa"/><rect x="112" y="90" width="20" height="18" rx="4" transform="rotate(-5 112 90)" fill="#af91d3"/><path d="m117 98 4 3 6-8" stroke="white" stroke-width="2" stroke-linecap="round"/><rect x="145" y="87" width="20" height="18" rx="4" transform="rotate(-5 145 87)" fill="#eee6fa"/><circle cx="184" cy="122" r="25" fill="#c7dbc9" stroke="#eee8f9" stroke-width="5"/><path d="m174 122 7 7 12-13" stroke="#739a7b" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><path d="m32 74 3-8 3 8 8 3-8 3-3 8-3-8-8-3 8-3Z" fill="#b59bcf"/><circle cx="212" cy="52" r="4" fill="#d2bedf"/><circle cx="45" cy="120" r="3" fill="#d2bedf"/></svg>`; }
function footer() { return `<footer class="footer"><span><b class="footer-brand">forma.</b><span>Uno spazio per far crescere la formazione.</span></span><span>${I('shield')} Dati salvati in questo browser</span></footer>`; }
function heading(title, subtitle, action = '') { return `<div class="page-heading"><div><h1>${E(title)}${db.demo ? '<span class="demo-badge">DEMO</span>' : ''}</h1><p class="subtitle">${E(subtitle)}</p></div><div class="heading-actions">${action}</div></div>`; }
function button(label, action, icon = 'plus', primary = true, extras = '') { return `<button class="btn ${primary ? 'primary' : ''}" data-action="${action}" ${extras}>${I(icon)}${label}</button>`; }
function emptyPage(icon, title, description, action = '') { return `<div class="empty-page"><div class="empty-graphic">${I(icon)}</div><h2>${title}</h2><p>${description}</p>${action}</div>`; }
function render() {
  const active = document.activeElement, focusId = active?.id, start = active?.selectionStart, end = active?.selectionEnd;
  document.title = `${pages[view]} — Forma`;
  app.innerHTML = `<aside class="sidebar"><a class="brand" href="#panoramica" aria-label="Forma, panoramica"><span class="brand-mark"><i></i><i></i><i></i><i></i></span>forma<span style="color:#a997cd">.</span></a><button class="workspace" data-action="settings"><span class="workspace-avatar">${I('teacher')}</span><span><strong>${E(db.schoolName)}</strong><small>Spazio della segreteria</small></span>${I('down')}</button><p class="nav-label">GESTIONE SCUOLA</p><nav class="nav" aria-label="Navigazione principale">${navLink('panoramica','grid')}${navLink('allievi','users',db.students.length)}${navLink('classi','book')}${navLink('docenti','teacher')}${navLink('calendario','calendar')}${navLink('aule','door')}<div class="nav-divider"></div>${navLink('impostazioni','settings')}</nav><div class="sidebar-bottom"><div class="help-card"><div class="help-icon">${I('spark')}</div><strong>Un buon inizio, insieme.</strong><p>Configura la tua scuola,<br>un piccolo passo alla volta.</p><button data-action="guide">Guida ai primi passi ${I('arrow')}</button></div><button class="user" data-action="settings"><span class="avatar">SG</span><span><strong>Segreteria</strong><small>Amministrazione</small></span>${I('down')}</button></div></aside><div class="mobile-scrim" data-action="close-menu"></div><div class="shell"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Apri menu">${I('menu')}</button>${I('grid')}<span>Spazio di lavoro</span><span>/</span><span>${pages[view]}</span></div><div class="topbar-actions"><button class="global-search" data-action="search" aria-label="Cerca in tutto il CRM">${I('search')}<span>Cerca nella tua scuola...</span><kbd>⌘ K</kbd></button><button class="icon-btn notification" data-action="activity" aria-label="Registro attività">${I('bell')}</button><button class="avatar" data-action="settings" aria-label="Impostazioni della segreteria" style="border:0">SG</button></div></header><main id="main">${storageNotice ? `<div class="section-note">${I('info')}${E(storageNotice)}</div>` : ''}${({panoramica:dashboard,allievi:studentsPage,classi:classesPage,docenti:teachersPage,calendario:calendarPage,aule:roomsPage,impostazioni:settingsPage}[view])()}${footer()}</main></div>`;
  if (focusId) { const el = document.getElementById(focusId); if (el) { el.focus({preventScroll:true}); if (typeof start === 'number' && ['text','search'].includes(el.type)) el.setSelectionRange(start,end); } }
}
function statsCard(label, icon, value, foot, color = '') { return `<div class="stat"><div class="stat-label">${label}<span class="stat-icon">${I(icon)}</span></div><div class="stat-value">${value}</div><div class="stat-foot"><i class="dot ${color}"></i>${foot}</div></div>`; }
function lessonsOn(date, shift) { return db.lessons.filter(l => l.date === date && (!shift || db.classes.find(c => c.id === l.classId)?.shift === shift)).sort((a,b) => a.start.localeCompare(b.start)); }
function occupiedRooms(date, shift) { return new Set(lessonsOn(date,shift).map(l => l.roomId)); }
function roomCardGrid(compact = false) {
  const used = occupiedRooms(compact ? selectedDate : roomDate, roomShift);
  return ROOMS.map(r => {
    const available = roomsForShift(roomShift).some(a => a.id === r.id), occupied = used.has(r.id);
    const list = lessonsOn(roomDate,roomShift).filter(l => l.roomId === r.id);
    if (compact) return `<button class="room-tile ${!available ? 'unavailable' : occupied ? 'occupied' : ''}" data-action="room-details" data-id="${r.id}" aria-label="${r.name}: ${!available ? 'non disponibile nel pomeriggio' : occupied ? 'con lezioni in programma' : 'libera'}">${I('door')}<span>${r.name}</span></button>`;
    return `<article class="room-card ${!available ? 'unavailable' : ''}"><div class="room-card-top">${I('door')}<span class="pill ${!available ? 'gray' : occupied ? '' : 'green'}">${!available ? 'Non disponibile' : occupied ? 'Prenotata' : 'Libera'}</span></div><h3>${r.name}</h3><p>Fino a 15 allievi per classe</p>${available ? `<button class="btn text" data-action="room-details" data-id="${r.id}">${list.length ? `${list.length} lezion${list.length === 1 ? 'e' : 'i'} in programma` : 'Visualizza disponibilità'} ${I('arrow')}</button>` : '<small>Disponibile nella fascia mattino</small>'}</article>`;
  }).join('');
}
function dashboard() {
  const initial = !db.classes.length && !db.students.length && !db.teachers.length;
  const morning = occupiedRooms(selectedDate,'morning').size, afternoon = occupiedRooms(selectedDate,'afternoon').size;
  const week = monday(selectedDate), lessons = lessonsOn(selectedDate);
  return `${heading('Panoramica','La tua scuola, a colpo d’occhio.',`<span class="date-tag">${I('calendar')}${dateFmt(today(),{weekday:'long',day:'numeric',month:'long'})}</span>${button('Nuova classe','create-class')}`)}${initial ? `<section class="welcome-banner"><div><div class="eyebrow">BENVENUTO IN FORMA</div><h2>Ogni grande percorso inizia da qui.</h2><p>Allievi, classi e persone. Tutto ciò che serve alla tua scuola,<br class="desktop-break"> finalmente in un unico spazio.</p><div>${button('Crea la prima classe','create-class')}<button class="btn text" data-action="load-demo">Esplora con dati demo ${I('arrow')}</button></div></div>${bannerArt()}</section>` : ''}<section class="stats" aria-label="Riepilogo della scuola">${statsCard('Allievi iscritti','users',db.students.length,`${db.students.filter(s=>s.status==='active').length} attivi nella tua scuola`)}${statsCard('Classi attive','book',db.classes.filter(c=>c.status==='active').length,`${db.classes.filter(c=>c.status==='planned').length} classi in partenza`,'green')}${statsCard('Aule mattino','sun',`${morning}<span class="denominator"> / 10</span>`,`${10-morning} aule senza lezioni`,'gold')}${statsCard('Aule pomeriggio','sunset',`${afternoon}<span class="denominator"> / 4</span>`,`${4-afternoon} aule senza lezioni`,'blue')}</section><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h2>Agenda della giornata</h2><small>Il prossimo passo, sempre in vista.</small></div><span class="date-display">${I('calendar')}${dateFmt(selectedDate,{month:'long',year:'numeric'})}</span></div><div class="week-strip">${Array.from({length:7},(_,i) => { const d = addDays(week,i); return `<button class="day ${d === selectedDate ? 'selected' : ''} ${lessonsOn(d).length ? 'has-event' : ''}" data-action="select-day" data-date="${d}" aria-label="${dateFmt(d)}" aria-pressed="${d===selectedDate}"><span>${dateFmt(d,{weekday:'short'}).replace('.','')}</span><b>${parseDate(d).getDate()}</b></button>`; }).join('')}</div>${lessons.length ? `<div class="agenda-list">${lessons.slice(0,3).map(l=>`<div class="agenda-item"><div class="agenda-time">${l.start}<small>${l.end}</small></div><div class="agenda-line"></div><div class="agenda-details"><strong>${E(className(l.classId))}</strong><small>${E(teacherName(db.classes.find(c=>c.id===l.classId)?.teacherId))}</small></div><span class="pill">${roomName(l.roomId)}</span><button class="icon-btn" data-action="edit-lesson" data-id="${E(l.id)}" aria-label="Modifica lezione">${I('chevron')}</button></div>`).join('')}</div>` : `<div class="agenda-empty"><div class="empty-graphic">${I('calendar')}</div><h3>Una giornata tutta da scrivere.</h3><p>Nessuna lezione in programma per ${selectedDate === today() ? 'oggi' : 'questa data'}.</p><button class="btn text" data-action="create-lesson">Pianifica una lezione ${I('plus')}</button></div>`}<div class="agenda-footer"><span>${I('clock')}${lessons.length} lezion${lessons.length===1?'e':'i'} in programma</span><button class="btn text" data-action="calendar" style="font-size:9px">Apri calendario ${I('arrow')}</button></div></section><section class="panel"><div class="panel-header"><div><h2>Le tue aule</h2><small>Lo spazio giusto per ogni percorso.</small></div><button class="icon-btn" data-action="rooms" aria-label="Gestisci aule">${I('chevron')}</button></div><div class="segmented" aria-label="Fascia oraria"><button class="${roomShift==='morning'?'active':''}" data-action="room-shift" data-shift="morning" aria-pressed="${roomShift==='morning'}">${I('sun')}Mattino</button><button class="${roomShift==='afternoon'?'active':''}" data-action="room-shift" data-shift="afternoon" aria-pressed="${roomShift==='afternoon'}">${I('sunset')}Pomeriggio</button></div><div class="room-status"><span>${roomShift==='morning'?'10':'4'} aule disponibili nella fascia</span><strong>${roomsForShift(roomShift).length - occupiedRooms(selectedDate,roomShift).size} libere tutto il giorno</strong></div><div class="room-grid">${roomCardGrid(true)}</div><div class="legend"><span><i class="legend-dot"></i>Libera</span><span><i class="legend-dot purple"></i>Con lezioni</span><span><i class="legend-dot gray"></i>Non disponibile</span></div><div class="capacity-note">${I('info')}Ogni classe può accogliere al massimo 15 allievi.</div></section></div><section class="panel table-panel"><div class="panel-header"><div><h2>Classi in evidenza</h2><small>I percorsi che stanno prendendo forma.</small></div><button class="btn text" data-action="classes">Tutte le classi ${I('arrow')}</button></div><div class="table-wrap"><table><thead><tr><th>CLASSE / CORSO</th><th>DOCENTE</th><th>FASCIA</th><th>ALLIEVI</th><th>STATO</th><th></th></tr></thead><tbody>${db.classes.length ? db.classes.slice(0,4).map((c,i) => classRow(c,i,true)).join('') : `<tr class="table-empty"><td colspan="6">${I('book')}<strong>La prima classe è un nuovo inizio.</strong><p>Crea un percorso, assegna un docente e accogli i tuoi allievi.</p></td></tr>`}</tbody></table></div><div class="panel-bottom"><span>${db.classes.length} classi nella tua scuola</span><span>Massimo 15 allievi per classe ${I('shield')}</span></div></section>`;
}
function classRow(c, i, compact = false) { const count = enrolled(c.id).length; return `<tr><td><button class="entity-name" data-action="class-details" data-id="${E(c.id)}" style="border:0;background:none;padding:0;text-align:left"><span class="class-icon class-color-${i%4}">${I('book')}</span><span><strong>${E(c.name)}</strong><small>${E(c.course)}</small></span></button></td><td>${E(teacherName(c.teacherId))}</td><td><span class="pill ${c.shift==='morning'?'gold':''}">${I(c.shift==='morning'?'sun':'sunset')}${SHIFTS[c.shift]}</span>${!compact?`<small>${roomName(c.roomId)}</small>`:''}</td><td><span class="mini-progress"><i style="width:${count/15*100}%"></i></span>${count}<span style="color:#b5a6c1"> / 15</span></td><td>${statusPill(c.status)}</td><td>${compact?`<button class="icon-btn" data-action="class-details" data-id="${E(c.id)}" aria-label="Dettagli ${E(c.name)}">${I('chevron')}</button>`:rowActions('class',c.id,c.name)}</td></tr>`; }
function rowActions(type,id,name) { return `<div class="table-actions"><button class="icon-btn" data-action="edit-${type}" data-id="${E(id)}" aria-label="Modifica ${E(name)}">${I('edit')}</button><button class="icon-btn" data-action="delete-${type}" data-id="${E(id)}" aria-label="Elimina ${E(name)}">${I('trash')}</button></div>`; }
function queryField(page, placeholder) { return `<label class="input-search">${I('search')}<input id="filter-${page}" type="search" data-filter="${page}" value="${E(filters[page].q)}" placeholder="${placeholder}" aria-label="${placeholder}"></label>`; }
function studentsPage() {
  const f = filters.allievi;
  const list = db.students.filter(s => (f.status==='all' || (f.status==='unassigned' ? !s.classId : s.status===f.status)) && `${fullName(s)} ${s.email} ${className(s.classId)}`.toLowerCase().includes(f.q.toLowerCase())).sort((a,b)=>a.lastName.localeCompare(b.lastName,'it'));
  return `${heading('Allievi','Persone, contatti e percorsi di formazione.',button('Nuovo allievo','create-student'))}<section class="panel"><div class="toolbar"><div class="filters">${[['all','Tutti'],['active','Attivi'],['waiting','In attesa'],['unassigned','Senza classe']].map(([value,label])=>`<button class="filter-btn ${f.status===value?'active':''}" data-action="student-filter" data-value="${value}">${label}${value==='all'?` · ${db.students.length}`:''}</button>`).join('')}</div>${queryField('allievi','Cerca un allievo...')}</div>${!db.students.length ? emptyPage('users','Le persone al centro.','Inizia con la prima anagrafica. Potrai assegnare ogni allievo a una classe e ritrovare qui tutti i suoi contatti.',button('Aggiungi il primo allievo','create-student')) : `<div class="table-wrap"><table><thead><tr><th>ALLIEVO</th><th>CONTATTI</th><th>CLASSE</th><th>STATO</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td><button class="entity-name" data-action="student-details" data-id="${E(s.id)}" style="border:0;background:none;padding:0;text-align:left"><span class="avatar">${E(initials(s))}</span><span><strong>${E(fullName(s))}</strong><small>Iscritto il ${dateFmt(s.createdAt||today(),{day:'numeric',month:'short',year:'numeric'})}</small></span></button></td><td>${E(s.email||'Email da aggiungere')}<small>${E(s.phone||'Telefono da aggiungere')}</small></td><td>${s.classId?E(className(s.classId)):'<span class="pill gray">Da assegnare</span>'}</td><td>${statusPill(s.status,true)}</td><td>${rowActions('student',s.id,fullName(s))}</td></tr>`).join('') || '<tr><td colspan="5" class="no-results">Nessun allievo corrisponde alla ricerca.</td></tr>'}</tbody></table></div><div class="panel-bottom"><span>${list.length} allievi visualizzati</span><span>${db.students.length} in totale</span></div>`}</section>`;
}
function classesPage() {
  const f = filters.classi;
  const list = db.classes.filter(c => (f.shift==='all'||c.shift===f.shift) && `${c.name} ${c.course} ${teacherName(c.teacherId)}`.toLowerCase().includes(f.q.toLowerCase()));
  return `${heading('Classi e corsi','Dai forma ai percorsi della tua scuola.',button('Nuova classe','create-class'))}<div class="section-note">${I('shield')}<span>Piccoli gruppi, grandi possibilità. <strong>Fino a 15 allievi per classe.</strong> Le iscrizioni oltre il limite vengono bloccate.</span></div><section class="panel"><div class="toolbar"><div class="filters">${[['all','Tutte le classi'],['morning','Mattino'],['afternoon','Pomeriggio']].map(([value,label])=>`<button class="filter-btn ${f.shift===value?'active':''}" data-action="class-filter" data-value="${value}">${label}</button>`).join('')}</div>${queryField('classi','Cerca una classe o un corso...')}</div>${!db.classes.length?emptyPage('book','Il prossimo percorso prende forma.','Crea una classe, scegli la fascia oraria e assegna un’aula. Potrai aggiungere allievi e lezioni in qualsiasi momento.',button('Crea la prima classe','create-class')):`<div class="table-wrap"><table><thead><tr><th>CLASSE / CORSO</th><th>DOCENTE</th><th>FASCIA / AULA</th><th>ALLIEVI</th><th>STATO</th><th></th></tr></thead><tbody>${list.map((c,i)=>classRow(c,i)).join('')||'<tr><td colspan="6" class="no-results">Nessuna classe corrisponde alla ricerca.</td></tr>'}</tbody></table></div><div class="panel-bottom"><span>${list.length} classi visualizzate</span><span>10 aule al mattino · 4 al pomeriggio</span></div>`}</section>`;
}
function teachersPage() {
  const list = db.teachers.filter(t=>`${fullName(t)} ${t.subject} ${t.email}`.toLowerCase().includes(filters.docenti.q.toLowerCase()));
  return `${heading('Docenti','Le competenze che fanno crescere la tua scuola.',button('Nuovo docente','create-teacher'))}<section class="panel"><div class="toolbar"><span class="subtitle">${db.teachers.length} docenti nella tua scuola</span>${queryField('docenti','Cerca un docente...')}</div>${!db.teachers.length?emptyPage('teacher','Ogni percorso ha la sua guida.','Aggiungi il team docente, raccogli i contatti e assegna le competenze alle tue classi.',button('Aggiungi il primo docente','create-teacher')):`<div class="table-wrap"><table><thead><tr><th>DOCENTE</th><th>AREA FORMATIVA</th><th>CONTATTI</th><th>CLASSI ASSEGNATE</th><th></th></tr></thead><tbody>${list.map(t=>`<tr><td><div class="entity-name"><span class="avatar">${E(initials(t))}</span><strong>${E(fullName(t))}</strong></div></td><td>${E(t.subject||'Da specificare')}</td><td>${E(t.email||'Email da aggiungere')}<small>${E(t.phone||'Telefono da aggiungere')}</small></td><td>${db.classes.filter(c=>c.teacherId===t.id).length} classi</td><td>${rowActions('teacher',t.id,fullName(t))}</td></tr>`).join('')||'<tr><td colspan="5" class="no-results">Nessun docente corrisponde alla ricerca.</td></tr>'}</tbody></table></div>`}</section>`;
}
function calendarPage() {
  const days = Array.from({length:7},(_,i)=>addDays(calendarWeek,i));
  const earliest = Math.min(8,Math.floor(minutes(db.hours.morningStart)/60)), latest = Math.max(19,Math.ceil(minutes(db.hours.afternoonEnd)/60));
  const scale = 49, duration = latest-earliest, weekLessons = db.lessons.filter(l=>days.includes(l.date));
  return `${heading('Calendario','Ogni lezione, al posto giusto.',button('Nuova lezione','create-lesson'))}<div class="page-subheading"><div class="schedule-controls"><button class="icon-btn" data-action="prev-week" aria-label="Settimana precedente">${I('left')}</button><span class="schedule-date">${dateFmt(days[0],{day:'numeric',month:'short'})} – ${dateFmt(days[6],{day:'numeric',month:'short',year:'numeric'})}</span><button class="icon-btn" data-action="next-week" aria-label="Settimana successiva">${I('chevron')}</button><button class="btn" data-action="today-week">Oggi</button></div><span class="date-tag">${I('shield')}Controllo automatico dei conflitti</span></div><section class="panel"><div class="table-wrap"><div class="schedule-grid"><div class="schedule-head"></div>${days.map(d=>`<div class="schedule-head ${d===today()?'today':''}">${dateFmt(d,{weekday:'short'}).toUpperCase()}<strong>${parseDate(d).getDate()}</strong></div>`).join('')}<div class="time-col">${Array.from({length:duration},(_,i)=>`<span>${String(i+earliest).padStart(2,'0')}:00</span>`).join('')}</div>${days.map(d=>{
    const lessons = lessonsOn(d); const lanes = [];
    const positions = lessons.map(l=>{let lane=lanes.findIndex(end=>end<=minutes(l.start));if(lane<0)lane=lanes.length;lanes[lane]=minutes(l.end);return {l,lane};});
    return `<div class="schedule-day" style="height:${duration*scale}px;min-height:${duration*scale}px">${positions.map(({l,lane},i)=>{const concurrent=positions.filter(p=>minutes(p.l.start)<minutes(l.end)&&minutes(l.start)<minutes(p.l.end));const cols=Math.max(...concurrent.map(p=>p.lane))+1;return `<button class="lesson-block ${i%2?'alt':''}" style="top:${(minutes(l.start)/60-earliest)*scale}px;height:${Math.max(31,(minutes(l.end)-minutes(l.start))/60*scale-3)}px;left:calc(${lane/cols*100}% + 3px);width:calc(${100/cols}% - 6px)" data-action="edit-lesson" data-id="${E(l.id)}" aria-label="${E(className(l.classId))}, ${l.start}–${l.end}, ${roomName(l.roomId)}"><span>${l.start} – ${l.end}</span><strong>${E(className(l.classId))}</strong><small>${roomName(l.roomId)}</small></button>`;}).join('')}</div>`;
  }).join('')}</div></div>${!weekLessons.length?'<div class="calendar-empty">La settimana è ancora libera. Aggiungi la prima lezione per iniziare a pianificare.</div>':`<div class="panel-bottom"><span>${weekLessons.length} lezioni questa settimana</span><span>Seleziona una lezione per modificarla</span></div>`}</section>`;
}
function roomsPage() { return `${heading('Aule','Uno spazio per imparare. Un posto per ogni classe.',button('Pianifica lezione','create-lesson'))}<div class="section-note">${I('info')}<span><strong>10 aule al mattino, 4 al pomeriggio.</strong> Le aule 01–04 sono attive in entrambe le fasce. Le prenotazioni con orari sovrapposti vengono bloccate.</span></div><div class="page-subheading"><div class="segmented"><button class="${roomShift==='morning'?'active':''}" data-action="room-shift" data-shift="morning">${I('sun')}Mattino</button><button class="${roomShift==='afternoon'?'active':''}" data-action="room-shift" data-shift="afternoon">${I('sunset')}Pomeriggio</button></div><label class="date-display">Data <input type="date" id="room-date" value="${roomDate}" aria-label="Data disponibilità aule"></label></div><div class="room-page-grid">${roomCardGrid()}</div>`; }
function settingsPage() { return `${heading('Impostazioni','Le basi della tua organizzazione, tutte qui.')}<div class="settings-grid"><section class="panel settings-panel"><h2>La tua scuola</h2><p>Personalizza lo spazio e gli orari di pianificazione.</p><form id="settings-form" data-entity="settings"><div class="form-grid">${field('Nome della scuola','schoolName',db.schoolName,'text',true,'full','maxlength="80"')}${field('Inizio mattino','morningStart',db.hours.morningStart,'time',true)}${field('Fine mattino','morningEnd',db.hours.morningEnd,'time',true)}${field('Inizio pomeriggio','afternoonStart',db.hours.afternoonStart,'time',true)}${field('Fine pomeriggio','afternoonEnd',db.hours.afternoonEnd,'time',true)}</div><div class="form-error" role="alert"></div><div class="form-actions"><button class="btn primary" type="submit">${I('check')}Salva impostazioni</button></div></form></section><section class="panel settings-panel"><h2>Le regole della tua scuola</h2><p>Questi limiti vengono controllati durante iscrizioni e pianificazione.</p><div class="rule-row">${I('users')}<div><strong>Allievi per classe</strong><small>Il limite include tutti gli iscritti alla classe</small></div><b>15</b></div><div class="rule-row">${I('sun')}<div><strong>Aule al mattino</strong><small>Aule 01–10</small></div><b>10</b></div><div class="rule-row">${I('sunset')}<div><strong>Aule al pomeriggio</strong><small>Aule 01–04</small></div><b>4</b></div><p class="storage-note">Le fasce orarie iniziali sono modificabili. I nuovi orari devono essere compatibili con le lezioni già registrate.</p></section><section class="panel settings-panel"><h2>Archivio e copie di sicurezza</h2><p>I dati rimangono nel browser di questo dispositivo. Esporta una copia per conservarli o trasferirli.</p><div class="backup-actions">${button('Esporta archivio','export','download',false)}${button('Ripristina archivio','import','upload',false)}</div><input type="file" id="import-file" accept=".json,application/json" hidden><p class="storage-note">Questa struttura iniziale non sincronizza i dati tra dispositivi e non include account per il personale. Il ripristino sostituisce l’archivio locale solo dopo la conferma.</p><div class="danger-box"><button class="btn danger small-btn" data-action="reset">${I('trash')}Svuota archivio</button></div></section><section class="panel settings-panel"><h2>Primi passi</h2><p>Uno spazio semplice, pronto per crescere con la scuola.</p><div class="backup-actions">${button('Apri la guida','guide','help',false)}${button(db.demo?'Ricarica dati demo':'Prova i dati demo','load-demo','spark',false)}</div><p class="storage-note">I dati di esempio sono interamente fittizi. Il caricamento sostituisce i dati correnti dopo una conferma; puoi prima esportarli.</p></section></div>`; }
function field(label, name, value = '', type = 'text', required = false, cls = '', attrs = '') { return `<label class="field ${cls}"><span>${label}${required?' <span aria-hidden="true">*</span>':''}</span><input name="${name}" type="${type}" value="${E(value)}" ${required?'required':''} ${attrs}></label>`; }
function selectField(label, name, options, value, cls = '', required = false) { return `<label class="field ${cls}"><span>${label}${required?' <span aria-hidden="true">*</span>':''}</span><select name="${name}" ${required?'required':''}>${options.map(([v,l])=>`<option value="${E(v)}" ${String(value)===String(v)?'selected':''}>${E(l)}</option>`).join('')}</select></label>`; }
function formShell(entity,id,content,submitLabel='Salva') { return `<form data-entity="${entity}" data-id="${E(id||'')}"><div class="form-grid">${content}</div><div class="form-error" role="alert"></div><div class="form-actions">${entity==='lesson'&&id?`<button type="button" class="btn danger" data-action="delete-lesson" data-id="${E(id)}" style="margin-right:auto">${I('trash')}Elimina</button>`:''}<button type="button" class="btn" data-action="close-modal">Annulla</button><button type="submit" class="btn primary">${I('check')}${submitLabel}</button></div></form>`; }
function openDialog(title, description, content) { modal.innerHTML = `<div class="modal-header"><div><h2 id="modal-title">${E(title)}</h2><p>${E(description)}</p></div><button class="icon-btn" data-action="close-modal" aria-label="Chiudi finestra">${I('close')}</button></div><div class="modal-content">${content}</div>`; if(!modal.open)modal.showModal(); }
function showStudent(id, presetClass = '') { const s = db.students.find(x=>x.id===id)||{firstName:'',lastName:'',email:'',phone:'',classId:presetClass,status:'active',notes:''}; openDialog(id?'Modifica allievo':'Nuovo allievo','Una nuova persona, un nuovo percorso. I campi con * sono obbligatori.',formShell('student',id,`${field('Nome','firstName',s.firstName,'text',true,'','maxlength="80" autocomplete="given-name"')}${field('Cognome','lastName',s.lastName,'text',true,'','maxlength="80" autocomplete="family-name"')}${field('Email','email',s.email,'email',false,'','maxlength="200"')}${field('Telefono','phone',s.phone,'tel',false,'','maxlength="40"')}${selectField('Classe','classId',[['','Da assegnare'],...db.classes.map(c=>[c.id,`${c.name} · ${enrolled(c.id).length}/15${enrolled(c.id).length>=15?' · Completa':''}`])],s.classId)}${selectField('Stato','status',[['active','Attivo'],['waiting','In attesa'],['inactive','Non attivo']],s.status)}<label class="field full"><span>Note</span><textarea name="notes" maxlength="2000" placeholder="Informazioni utili per la segreteria...">${E(s.notes)}</textarea></label>`,'Salva allievo')); }
function showClass(id) { const c = db.classes.find(x=>x.id===id)||{name:'',course:'',teacherId:'',shift:'morning',roomId:'r1',status:'planned',startDate:'',endDate:''}; openDialog(id?'Modifica classe':'Nuova classe','Un gruppo, un obiettivo. Massimo 15 allievi per classe.',formShell('class',id,`${field('Nome della classe','name',c.name,'text',true,'full','maxlength="100" placeholder="Es. Competenze digitali · Edizione 1"')}${field('Corso / area formativa','course',c.course,'text',true,'full','maxlength="120" placeholder="Es. Formazione informatica"')}${selectField('Docente','teacherId',[['','Da assegnare'],...db.teachers.map(t=>[t.id,fullName(t)])],c.teacherId)}${selectField('Stato','status',[['planned','In partenza'],['active','Attiva'],['finished','Conclusa']],c.status)}${selectField('Fascia oraria','shift',Object.entries(SHIFTS),c.shift)}${selectField('Aula di riferimento','roomId',roomsForShift(c.shift).map(r=>[r.id,r.name]),c.roomId)}${field('Data di inizio','startDate',c.startDate,'date')}${field('Data di fine','endDate',c.endDate,'date')}<div class="section-note full" style="margin:0;font-size:10px">${I('info')}L’aula di riferimento non riserva uno spazio. La prenotazione avviene quando pianifichi una lezione.</div>`,'Salva classe')); }
function showTeacher(id) { const t = db.teachers.find(x=>x.id===id)||{firstName:'',lastName:'',subject:'',email:'',phone:''}; openDialog(id?'Modifica docente':'Nuovo docente','Le persone che danno valore alla formazione.',formShell('teacher',id,`${field('Nome','firstName',t.firstName,'text',true,'','maxlength="80"')}${field('Cognome','lastName',t.lastName,'text',true,'','maxlength="80"')}${field('Area formativa','subject',t.subject,'text',false,'full','maxlength="120" placeholder="Es. Informatica, comunicazione, sicurezza..."')}${field('Email','email',t.email,'email',false,'','maxlength="200"')}${field('Telefono','phone',t.phone,'tel',false,'','maxlength="40"')}`,'Salva docente')); }
function showLesson(id, presetClass = '', presetRoom = '') {
  const activeClasses = db.classes.filter(c=>c.status!=='finished');
  if (!activeClasses.length && !id) { openDialog('Prima, una classe','Le lezioni appartengono sempre a un percorso.',`<div class="agenda-empty"><div class="empty-graphic">${I('book')}</div><h3>Crea la tua prima classe</h3><p>Potrai poi scegliere una data, un’aula e un orario.</p>${button('Crea una classe','create-class')}</div>`); return; }
  const l = db.lessons.find(x=>x.id===id) || {classId:presetClass||activeClasses[0]?.id,date:view==='aule'?roomDate:view==='panoramica'?selectedDate:calendarWeek===monday(today())?today():calendarWeek,roomId:presetRoom,start:'',end:'',notes:''};
  const c = db.classes.find(x=>x.id===l.classId) || activeClasses[0];
  openDialog(id?'Modifica lezione':'Nuova lezione','Aula, classe e docente vengono controllati per evitare sovrapposizioni.',formShell('lesson',id,`${selectField('Classe','classId',db.classes.filter(c=>c.status!=='finished'||c.id===l.classId).map(c=>[c.id,`${c.name} · ${SHIFTS[c.shift]}`]),l.classId,'full',true)}${field('Data','date',l.date,'date',true)}${selectField('Aula','roomId',roomsForShift(c.shift).map(r=>[r.id,r.name]),l.roomId||c.roomId,'',true)}${field('Ora di inizio','start',l.start||db.hours[`${c.shift}Start`],'time',true)}${field('Ora di fine','end',l.end||`${String(Math.min(23,Math.floor(minutes(db.hours[`${c.shift}Start`])/60)+1)).padStart(2,'0')}:${db.hours[`${c.shift}Start`].slice(3)}`,'time',true)}<div class="section-note full" id="lesson-hint" style="font-size:10px;margin:0">${I('clock')}${SHIFTS[c.shift]} · ${db.hours[`${c.shift}Start`]}–${db.hours[`${c.shift}End`]} · ${E(teacherName(c.teacherId))}</div><label class="field full"><span>Note della lezione</span><textarea name="notes" maxlength="2000" placeholder="Argomento, materiali o indicazioni...">${E(l.notes)}</textarea></label>`,'Salva lezione'));
}
function classDetails(id) { const c = db.classes.find(c=>c.id===id); if(!c)return; const students = enrolled(id); openDialog(c.name,c.course,`<dl class="detail-list"><div><dt>DOCENTE</dt><dd>${E(teacherName(c.teacherId))}</dd></div><div><dt>FASCIA E AULA DI RIFERIMENTO</dt><dd>${SHIFTS[c.shift]} · ${roomName(c.roomId)}</dd></div><div><dt>STATO</dt><dd>${statusPill(c.status)}</dd></div><div><dt>ALLIEVI</dt><dd>${students.length} / 15 posti</dd></div></dl><div class="panel-header" style="padding:10px 0"><h3>Allievi della classe</h3>${button('Aggiungi','student-in-class','plus',false,`data-id="${E(id)}" ${students.length>=15?'disabled':''}`)}</div>${students.map(s=>`<div class="student-mini"><span class="avatar">${E(initials(s))}</span>${E(fullName(s))}<button class="btn text" data-action="edit-student" data-id="${E(s.id)}" aria-label="Modifica ${E(fullName(s))}">${I('edit')}</button></div>`).join('')||'<p class="inline-empty">Questa classe è pronta ad accogliere i primi allievi.</p>'}<div class="form-actions">${button('Modifica classe','edit-class','edit',false,`data-id="${E(id)}"`)}${button('Pianifica lezione','lesson-in-class','calendar',true,`data-id="${E(id)}"`)}</div>`); }
function studentDetails(id) { const s = db.students.find(s=>s.id===id); if(!s)return; openDialog(fullName(s),'Scheda allievo',`<dl class="detail-list"><div><dt>EMAIL</dt><dd>${E(s.email||'Da aggiungere')}</dd></div><div><dt>TELEFONO</dt><dd>${E(s.phone||'Da aggiungere')}</dd></div><div><dt>CLASSE</dt><dd>${E(className(s.classId))}</dd></div><div><dt>STATO</dt><dd>${statusPill(s.status,true)}</dd></div></dl>${s.notes?`<h3>Note della segreteria</h3><p class="storage-note" style="white-space:pre-wrap">${E(s.notes)}</p>`:''}<div class="form-actions">${button('Modifica allievo','edit-student','edit',true,`data-id="${E(id)}"`)}</div>`); }
function roomDetails(id) { const date = view==='panoramica'?selectedDate:roomDate, available=roomsForShift(roomShift).some(r=>r.id===id), lessons=lessonsOn(date,roomShift).filter(l=>l.roomId===id); openDialog(roomName(id),`${dateFmt(date)} · ${SHIFTS[roomShift]}`,available?`${lessons.map(l=>`<div class="agenda-item"><div class="agenda-time">${l.start}<small>${l.end}</small></div><div class="agenda-line"></div><div class="agenda-details"><strong>${E(className(l.classId))}</strong><small>${E(teacherName(db.classes.find(c=>c.id===l.classId)?.teacherId))}</small></div><button class="icon-btn" data-action="edit-lesson" data-id="${E(l.id)}" aria-label="Modifica lezione">${I('edit')}</button></div>`).join('')||'<div class="inline-empty">Nessuna lezione in programma in questa fascia.</div>'}<p class="storage-note">L’aula può essere usata da più classi nella stessa giornata, in orari diversi.</p><div class="form-actions">${button('Pianifica qui','lesson-in-room','plus',true,`data-id="${E(id)}"`)}</div>`:'<p class="inline-empty">Questa aula è disponibile solo al mattino.<br>Nel pomeriggio sono attive le aule 01–04.</p>'); }
function guide() { openDialog('La tua scuola prende forma','Tre piccoli passi per cominciare.',`<div class="guide-step"><span class="step-number">1</span><div><strong>Conosci il tuo team</strong><p>Aggiungi i docenti e i loro contatti. Potrai assegnarli alle classi anche in seguito.</p></div></div><div class="guide-step"><span class="step-number">2</span><div><strong>Crea classi e accogli allievi</strong><p>Definisci corso, fascia oraria e aula di riferimento. Ogni classe ha un limite di 15 iscritti.</p></div></div><div class="guide-step"><span class="step-number">3</span><div><strong>Organizza le lezioni</strong><p>Pianifica dal calendario: 10 aule al mattino, 4 al pomeriggio. Forma segnala gli impegni sovrapposti di aule, classi e docenti.</p></div></div><div class="section-note" style="margin:20px 0 0">${I('download')}Ricorda di esportare l’archivio: i dati sono salvati solo nel browser di questo dispositivo.</div><div class="form-actions">${button('Cominciamo','create-class')}</div>`); }
function confirmDialog(title, description, label, action) { openDialog(title,description,`<p class="storage-note">${action==='confirm-reset'?'L’operazione rimuove allievi, classi, docenti e lezioni da questo browser. Esporta prima una copia se vuoi conservarli.':''}</p><div class="form-actions"><button class="btn" data-action="close-modal">Annulla</button><button class="btn ${action==='confirm-delete'||action==='confirm-reset'?'danger':'primary'}" data-action="${action}">${label}</button></div>`); }
let pendingDelete=null, pendingImport=null;
function askDelete(type,id) { const collection={student:'students',class:'classes',teacher:'teachers',lesson:'lessons'}[type], item=db[collection].find(x=>x.id===id); if(!item)return;pendingDelete={type,id,collection};const desc=type==='class'?`Gli allievi di “${item.name}” resteranno in anagrafica senza classe. Le lezioni collegate verranno rimosse.`:type==='teacher'?`Le classi di ${fullName(item)} resteranno senza docente.`:type==='lesson'?`Rimuovere la lezione del ${dateFmt(item.date)} alle ${item.start}?`:`Rimuovere ${fullName(item)} dall’anagrafica e dalla classe?`;confirmDialog(`Eliminare ${type==='class'?'la classe':type==='student'?'l’allievo':type==='teacher'?'il docente':'la lezione'}?`,desc,'Elimina','confirm-delete'); }
function exportData() { let data=JSON.stringify(db,null,2); if(storageNotice){try{data=localStorage.getItem(key)||data;}catch{}} const blob=new Blob([data],{type:'application/json'}), url=URL.createObjectURL(blob), link=document.createElement('a');link.href=url;link.download=`forma-archivio-${today()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Copia dell’archivio esportata.'); }
function makeDemo() {
  const d=blankState();d.demo=true;d.schoolName='Centro Formazione';
  d.teachers=[{id:'t1',firstName:'Giulia',lastName:'Moretti',subject:'Competenze digitali',email:'giulia.moretti@example.com',phone:''},{id:'t2',firstName:'Luca',lastName:'Rossi',subject:'Lingue e comunicazione',email:'luca.rossi@example.com',phone:''},{id:'t3',firstName:'Sara',lastName:'Bianchi',subject:'Formazione aziendale',email:'sara.bianchi@example.com',phone:''}];
  d.classes=[{id:'c1',name:'Competenze digitali · 01',course:'Informatica di base',teacherId:'t1',shift:'morning',roomId:'r1',status:'active',startDate:'',endDate:''},{id:'c2',name:'English for work · 02',course:'Inglese professionale',teacherId:'t2',shift:'morning',roomId:'r3',status:'active',startDate:'',endDate:''},{id:'c3',name:'Comunicare meglio · 01',course:'Comunicazione efficace',teacherId:'t3',shift:'afternoon',roomId:'r2',status:'active',startDate:'',endDate:''},{id:'c4',name:'Project management · 01',course:'Gestione dei progetti',teacherId:'t3',shift:'morning',roomId:'r4',status:'planned',startDate:'',endDate:''}];
  const names=[['Alessia','Romano'],['Marco','Conti'],['Elena','Ferrari'],['Andrea','Costa'],['Chiara','Ricci'],['Matteo','Marino'],['Sofia','Greco'],['Davide','Bruno'],['Francesca','Gallo'],['Lorenzo','Esposito'],['Martina','Fontana'],['Gabriele','Rizzo'],['Valentina','Lombardi'],['Simone','Barbieri'],['Federica','De Luca'],['Alessandro','Villa'],['Alice','Mancini'],['Tommaso','Colombo'],['Beatrice','Serra'],['Nicola','Ferri'],['Irene','Martini'],['Pietro','Leone'],['Emma','Gentile'],['Filippo','Riva']];
  d.students=names.map(([firstName,lastName],i)=>({id:`s${i+1}`,firstName,lastName,email:`allievo${i+1}@example.com`,phone:'',classId:i<10?'c1':i<18?'c2':i<23?'c3':'',status:i===23?'waiting':'active',notes:'',createdAt:today()}));
  let n=1;const week=monday(today());for(let i=0;i<5;i++){const date=addDays(week,i);if(i%2===0)d.lessons.push({id:`l${n++}`,classId:'c1',date,start:'09:00',end:'11:00',roomId:'r1',notes:'Introduzione agli strumenti digitali'});d.lessons.push({id:`l${n++}`,classId:'c2',date,start:'09:30',end:'11:00',roomId:'r3',notes:''});if(i<3)d.lessons.push({id:`l${n++}`,classId:'c3',date,start:'14:30',end:'16:00',roomId:'r2',notes:''});}
  d.activities=[{text:'Archivio dimostrativo caricato: tutti i dati sono fittizi.',at:new Date().toISOString()}];return d;
}

document.addEventListener('click', event => {
  const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;
  if(action==='close-modal'){modal.close();return;}
  if(action==='menu'){$('.sidebar').classList.add('open');return;}
  if(action==='close-menu'){$('.sidebar').classList.remove('open');return;}
  if(action==='settings'){modal.close();go('impostazioni');return;}
  if(action==='calendar'){go('calendario');return;}if(action==='classes'){go('classi');return;}if(action==='rooms'){roomDate=selectedDate;go('aule');return;}
  if(action==='create-student'||action==='edit-student'){showStudent(id);return;}
  if(action==='student-in-class'){showStudent('',id);return;}
  if(action==='create-class'||action==='edit-class'){showClass(id);return;}
  if(action==='create-teacher'||action==='edit-teacher'){showTeacher(id);return;}
  if(action==='create-lesson'||action==='edit-lesson'){showLesson(id);return;}
  if(action==='lesson-in-class'){showLesson('',id);return;}
  if(action==='lesson-in-room'){const c=db.classes.find(c=>c.shift===roomShift&&c.status!=='finished');if(!c){toast(`Crea prima una classe nella fascia ${SHIFTS[roomShift].toLowerCase()}.`);return;}showLesson('',c.id,id);return;}
  if(action==='class-details'){classDetails(id);return;}if(action==='student-details'){studentDetails(id);return;}if(action==='room-details'){roomDetails(id);return;}
  if(action==='guide'){guide();return;}
  if(action==='select-day'){selectedDate=el.dataset.date;render();return;}
  if(action==='room-shift'){roomShift=el.dataset.shift;render();return;}
  if(action==='student-filter'){filters.allievi.status=el.dataset.value;render();return;}
  if(action==='class-filter'){filters.classi.shift=el.dataset.value;render();return;}
  if(action==='prev-week'||action==='next-week'||action==='today-week'){calendarWeek=action==='today-week'?monday(today()):addDays(calendarWeek,action==='prev-week'?-7:7);render();return;}
  if(action.startsWith('delete-')){askDelete(action.slice(7),id);return;}
  if(action==='confirm-delete'&&pendingDelete){const {type,id,collection}=pendingDelete;const error=commit(next=>{next[collection]=next[collection].filter(x=>x.id!==id);if(type==='class'){next.students.forEach(s=>{if(s.classId===id)s.classId='';});next.lessons=next.lessons.filter(l=>l.classId!==id);}if(type==='teacher')next.classes.forEach(c=>{if(c.teacherId===id)c.teacherId='';});activity(next,'Elemento rimosso dall’archivio.');},'Elemento eliminato.');if(error){toast(error);return;}pendingDelete=null;modal.close();return;}
  if(action==='export'){exportData();return;}if(action==='import'){$('#import-file').click();return;}
  if(action==='confirm-import'&&pendingImport){const error=commit(next=>{Object.keys(next).forEach(k=>delete next[k]);Object.assign(next,pendingImport);},'Archivio ripristinato.');if(error){toast(error);return;}pendingImport=null;storageNotice='';modal.close();render();return;}
  if(action==='reset'){confirmDialog('Svuotare l’archivio?','Riparti da uno spazio vuoto. I dati presenti in questo browser verranno rimossi.','Svuota archivio','confirm-reset');return;}
  if(action==='confirm-reset'){const error=commit(next=>{Object.keys(next).forEach(k=>delete next[k]);Object.assign(next,blankState());},'Archivio svuotato. Un nuovo inizio.');if(error){toast(error);return;}storageNotice='';modal.close();go('panoramica');render();return;}
  if(action==='load-demo'){if(db.classes.length||db.students.length||db.teachers.length){confirmDialog('Caricare i dati demo?','L’archivio attuale verrà sostituito con dati fittizi. Esporta una copia dalle impostazioni se vuoi conservarlo.','Carica dati demo','confirm-demo');}else loadDemo();return;}
  if(action==='confirm-demo'){loadDemo();return;}
  if(action==='activity'){openDialog('Attività recenti','Le ultime modifiche in questo browser.',db.activities.length?db.activities.slice(0,15).map(a=>`<div class="agenda-item"><div class="empty-graphic" style="width:30px;height:30px;margin:0">${I('check')}</div><div class="agenda-details"><strong>${E(a.text)}</strong><small>${E(new Date(a.at).toLocaleString('it-IT',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}))}</small></div></div>`).join(''):'<div class="agenda-empty"><div class="empty-graphic">'+I('bell')+'</div><h3>Tutto pronto per cominciare.</h3><p>Le attività della scuola compariranno qui.</p></div>');return;}
  if(action==='search'){openSearch();return;}
  if(action==='search-result'){modal.close();if(el.dataset.type==='student'){go('allievi');studentDetails(id);}else if(el.dataset.type==='class'){go('classi');classDetails(id);}else{go('docenti');showTeacher(id);}return;}
});
function loadDemo(){const demo=makeDemo();const error=commit(next=>{Object.keys(next).forEach(k=>delete next[k]);Object.assign(next,demo);},'Dati dimostrativi caricati. Tutte le persone sono fittizie.');if(error){toast(error);return;}modal.close();selectedDate=today();go('panoramica');render();}
document.addEventListener('input', event=>{const el=event.target;if(el.dataset.filter){filters[el.dataset.filter].q=el.value;render();}if(el.id==='global-query')renderSearch(el.value);});
document.addEventListener('change', async event=>{
  const el=event.target;
  if(el.id==='room-date'){roomDate=el.value||today();render();}
  if(el.name==='shift'&&el.closest('[data-entity="class"]')){const room=el.form.elements.roomId,old=room.value;room.innerHTML=roomsForShift(el.value).map(r=>`<option value="${r.id}">${r.name}</option>`).join('');if(roomsForShift(el.value).some(r=>r.id===old))room.value=old;}
  if(el.name==='classId'&&el.closest('[data-entity="lesson"]')){const c=db.classes.find(c=>c.id===el.value),form=el.form;if(!c)return;form.elements.roomId.innerHTML=roomsForShift(c.shift).map(r=>`<option value="${r.id}" ${r.id===c.roomId?'selected':''}>${r.name}</option>`).join('');form.elements.start.value=db.hours[`${c.shift}Start`];form.elements.end.value=`${String(Math.floor(minutes(form.elements.start.value)/60)+1).padStart(2,'0')}:${form.elements.start.value.slice(3)}`;$('#lesson-hint').innerHTML=`${I('clock')}${SHIFTS[c.shift]} · ${db.hours[`${c.shift}Start`]}–${db.hours[`${c.shift}End`]} · ${E(teacherName(c.teacherId))}`;}
  if(el.id==='import-file'){const file=el.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('Il file supera il limite di 5 MB.');const value=JSON.parse(await file.text()),error=validateState(value);if(error)throw new Error(error);pendingImport=value;confirmDialog('Ripristinare questo archivio?',`${value.students.length} allievi, ${value.classes.length} classi, ${value.teachers.length} docenti e ${value.lessons.length} lezioni. Il ripristino sostituisce i dati correnti di questo browser.`,'Ripristina archivio','confirm-import');}catch(error){toast(`Archivio non importato: ${error.message}`);}el.value='';}
});
document.addEventListener('submit',event=>{
  const form=event.target;if(!form.dataset.entity)return;event.preventDefault();
  const values=Object.fromEntries(new FormData(form));Object.keys(values).forEach(k=>values[k]=values[k].trim());const type=form.dataset.entity,id=form.dataset.id;
  const error=commit(next=>{
    if(type==='settings'){next.schoolName=values.schoolName;for(const k of Object.keys(next.hours))next.hours[k]=values[k];activity(next,'Impostazioni della scuola aggiornate.');return;}
    const collection={student:'students',class:'classes',teacher:'teachers',lesson:'lessons'}[type],index=next[collection].findIndex(x=>x.id===id),record={...values,id:id||crypto.randomUUID()};
    if(type==='student')record.createdAt=index>=0?next.students[index].createdAt:today();
    if(index>=0)next[collection][index]=record;else next[collection].push(record);
    const name=type==='class'?record.name:type==='lesson'?`Lezione del ${dateFmt(record.date)}`:fullName(record);activity(next,`${index>=0?'Aggiornato':'Aggiunto'}: ${name}.`);
  },type==='settings'?'Impostazioni salvate.':`${type==='class'?'Classe salvata':type==='lesson'?'Lezione pianificata':type==='teacher'?'Docente salvato':'Allievo salvato'}.`);
  if(error){$('.form-error',form).textContent=error;return;}if(type!=='settings')modal.close();
});
function openSearch(){openDialog('Cerca nella tua scuola','Trova allievi, classi e docenti in un unico posto.',`<label class="input-search" style="max-width:none;margin:8px 0">${I('search')}<input id="global-query" type="search" placeholder="Digita un nome, una classe o un corso..." aria-label="Ricerca globale" autocomplete="off"></label><div class="search-results" id="search-results"><p class="inline-empty">Inizia a scrivere per cercare nell’archivio.</p></div>`);$('#global-query').focus();}
function renderSearch(query){const q=query.trim().toLowerCase();if(!q){$('#search-results').innerHTML='<p class="inline-empty">Inizia a scrivere per cercare nell’archivio.</p>';return;}const results=[...db.students.map(s=>({id:s.id,type:'student',name:fullName(s),sub:`Allievo · ${className(s.classId)}`,extra:s.email})),...db.classes.map(c=>({id:c.id,type:'class',name:c.name,sub:`Classe · ${c.course}`,extra:''})),...db.teachers.map(t=>({id:t.id,type:'teacher',name:fullName(t),sub:`Docente · ${t.subject||'Formazione'}`,extra:t.email}))].filter(r=>`${r.name} ${r.sub} ${r.extra}`.toLowerCase().includes(q)).slice(0,25);$('#search-results').innerHTML=results.map(r=>`<button class="search-result" data-action="search-result" data-type="${r.type}" data-id="${E(r.id)}">${I(r.type==='student'?'users':r.type==='class'?'book':'teacher')}<span><strong>${E(r.name)}</strong><small>${E(r.sub)}</small></span></button>`).join('')||'<p class="inline-empty">Nessun risultato. Prova con un altro nome.</p>';}
window.addEventListener('hashchange',()=>{view=pages[location.hash.slice(1)]?location.hash.slice(1):'panoramica';render();window.scrollTo({top:0});});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openSearch();}if(event.key==='Escape')$('.sidebar')?.classList.remove('open');});
modal.addEventListener('click',event=>{if(event.target===modal){const rect=modal.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)modal.close();}});
window.addEventListener('storage',event=>{if(event.key===key){try{const next=event.newValue?JSON.parse(event.newValue):blankState();if(!validateState(next)){db=next;render();toast('Archivio aggiornato da un’altra scheda.');}}catch{}}});
render();
